  constructor(private readonly scene: Scene, canvas: HTMLCanvasElement) {
    SceneLoader.OnPluginActivatedObservable.add((plugin) => {
      const gltfPlugin = plugin as unknown as { skipMaterials?: boolean };
      if ("skipMaterials" in gltfPlugin) gltfPlugin.skipMaterials = true;
    });
    scene.clearColor = new Color4(0.037, 0.07, 0.085, 1);
    scene.fogMode = Scene.FOGMODE_EXP2; scene.fogDensity = 0.017; scene.fogColor = new Color3(0.06, 0.11, 0.12);
    this.camera = new ArcRotateCamera("ferrosul-camera", -2.15, 1.08, 14, new Vector3(-7, 1.5, -9), scene);
    this.camera.lowerBetaLimit = 0.55; this.camera.upperBetaLimit = 1.38; this.camera.lowerRadiusLimit = 7; this.camera.upperRadiusLimit = 17; this.camera.wheelPrecision = 50; scene.activeCamera = this.camera;
    this.input = new InputManager(canvas);
    this.ui = new UIController({ startNewGame: () => this.startNewGame(), continueGame: () => void this.continueGame(), saveGame: () => void this.saveGame(), changeDifficulty: (difficulty) => { this.saveData.settings.difficulty = difficulty; this.ui.notify(`Dificuldade: ${difficulty}`); }, updateInvestigationLinks: (links) => this.updateInvestigationLinks(links), chooseGuildClue: (choice) => this.chooseGuildClue(choice), equipItem: (owner, itemId) => this.equipItem(owner, itemId), upgradeEquipment: (itemId) => this.upgradeEquipment(itemId), craftRecipe: (recipeId) => this.craftRecipe(recipeId), debugAction: (action) => this.debug(action) });
    this.createLighting(); this.createFerrosul(); this.createElwenThreshold(); this.createVeyraApproach();
    this.actors = { kael: new Actor(scene, CHARACTERS.kael, this.clearing.add(new Vector3(0, 0, 1))), dheren: new Actor(scene, CHARACTERS.dheren, this.clearing.add(new Vector3(2.3, 0, -1))), lyra: new Actor(scene, CHARACTERS.lyra, this.elwenPath.add(new Vector3(1.5, 0, -1.5))), mira: new Actor(scene, CHARACTERS.mira, this.miraAlley) };
    void Promise.all([this.actors.kael.loadVisual(), this.actors.dheren.loadVisual(), this.actors.lyra.loadVisual(), this.actors.mira.loadVisual()]);
    this.actors.kael.setActive(true); this.actors.lyra.root.setEnabled(false); this.actors.mira.root.setEnabled(false); this.ensureStarterEquipment(); this.applyEquipmentStats(); this.createInteractables(); this.createAmbientRunes();
  }
  async initialize() {
    const recovered = await this.saves.load();
    if (recovered) this.saveData = { ...defaultSave(), ...recovered, guildChoice: recovered.guildChoice ?? null, underwaysChallenges: recovered.underwaysChallenges ?? [], underwaysStealth: recovered.underwaysStealth ?? "pending", lanternReputation: recovered.lanternReputation ?? 0, lanternFactionUnlocked: recovered.lanternFactionUnlocked ?? false, lanternMissions: recovered.lanternMissions ?? [], soundTrapsTriggered: recovered.soundTrapsTriggered ?? [], equippedItems: { ...defaultSave().equippedItems, ...(recovered.equippedItems ?? {}) }, equipmentUpgrades: recovered.equipmentUpgrades ?? {}, upgradeTokens: recovered.upgradeTokens ?? 3, materials: { ...defaultSave().materials, ...(recovered.materials ?? {}) }, collectedMaterialNodes: recovered.collectedMaterialNodes ?? [], craftedRecipes: recovered.craftedRecipes ?? [], dailyCycleKey: recovered.dailyCycleKey ?? "", dailyMissions: recovered.dailyMissions ?? [], dynamicEvent: recovered.dynamicEvent ?? defaultSave().dynamicEvent };
    this.refreshDailyCycle();
    this.ensureStarterEquipment(); this.applyEquipmentStats();
    if (this.autoDemo) this.startDemo();
    else this.ui.showTitle();
    this.scene.onBeforeRenderObservable.add(() => this.update(this.scene.getEngine().getDeltaTime() / 1000));
  }
  private createLighting() {
    const sky = new HemisphericLight("cold-sky", new Vector3(0.2, 1, 0.1), this.scene); sky.intensity = 1.25; sky.diffuse = Color3.FromHexString("#9ed4dc"); sky.groundColor = Color3.FromHexString("#17201e");
    const sun = new DirectionalLight("distant-sun", new Vector3(-0.4, -1, 0.25), this.scene); sun.position = new Vector3(20, 35, -20); sun.intensity = 1.45; sun.diffuse = Color3.FromHexString("#ffd3a0");
    const forgeLight = new PointLight("forge-amber", this.forge.add(new Vector3(0, 3.3, 0)), this.scene); forgeLight.diffuse = Color3.FromHexString("#ff9b45"); forgeLight.intensity = 4.2; forgeLight.range = 22;
    const tavernLight = new PointLight("tavern-amber", this.tavern.add(new Vector3(0, 3, 0)), this.scene); tavernLight.diffuse = Color3.FromHexString("#e8b96c"); tavernLight.intensity = 2.4; tavernLight.range = 14;
  }
  private material(name: string, color: string, emissive = 0) {
    const value = Color3.FromHexString(color); const result = new StandardMaterial(name, this.scene); result.diffuseColor = value.scale(0.72); result.specularColor = Color3.Black(); result.emissiveColor = value.scale(emissive); this.villageMaterials.push(result); return result;
  }
