  private async loadVillageGlbs() {
    const assets = [
      { name: "kenney-barrels", url: "/manus-storage/barrels-embedded_06b8644c.glb", position: this.tavern.add(new Vector3(-3.3, 0, 1.8)), scale: 0.85, yaw: 0 },
      { name: "kenney-tower", url: "/manus-storage/tower-embedded_2dc7b707.glb", position: this.exit.add(new Vector3(-2.8, 0, -1.8)), scale: 1.12, yaw: 0.4 },
      { name: "kenney-tree-east", url: "/manus-storage/tree-large-embedded_6089226e.glb", position: new Vector3(24, 0, 16), scale: 1.45, yaw: 0 },
      { name: "kenney-tree-west", url: "/manus-storage/tree-large-embedded_6089226e.glb", position: new Vector3(-25, 0, 10), scale: 1.7, yaw: 1.2 },
      { name: "kenney-forge-frame", url: "/manus-storage/structure-embedded_74e52e4c.glb", position: this.forge.add(new Vector3(0, 0, 0.4)), scale: 1.26, yaw: 0 },
      { name: "kenney-tavern-roof", url: "/manus-storage/roof-embedded_bbf3282f.glb", position: this.tavern.add(new Vector3(0, 3.65, 0)), scale: 2.05, yaw: Math.PI / 2 },
    ];
    await Promise.all(assets.map(async (asset) => {
      try {
        const result = await SceneLoader.ImportMeshAsync("", "", asset.url, this.scene);
        const root = new TransformNode(asset.name, this.scene); root.position.copyFrom(asset.position); root.rotation.y = asset.yaw; root.scaling.setAll(asset.scale);
        result.meshes.filter((mesh) => !mesh.parent).forEach((mesh) => { mesh.parent = root; });
        result.meshes.forEach((mesh, index) => {
          const source = mesh.material as { albedoColor?: Color3; diffuseColor?: Color3 } | null;
          const color = source?.albedoColor ?? source?.diffuseColor ?? Color3.FromHexString("#6c5944");
          mesh.material = this.material(`${asset.name}-material-${index}`, color.toHexString());
        });
      } catch (error) { console.warn(`GLB de Ferrosul indisponível: ${asset.name}`, error); }
    }));
  }
