  private debug(action: string) { if (action === "heal") { Object.values(this.actors).forEach((member) => member.heal()); this.ui.notify("Party restaurada."); } if (action === "spawn") this.spawnEnemy("ashling", this.activeActor().root.position.add(new Vector3(0, 0, 4))); if (action === "kill") this.enemies.forEach((enemy) => enemy.hurt(enemy.health)); if (action === "attack") this.startAttack(true); if (action === "kael") this.setActive("kael"); if (action === "dheren") { if (!this.attackStarted) this.startAttack(true); this.setActive("dheren"); } }
